#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> cnt(1 << 10);
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        int m = 0;
        for (char c : s) m |= 1 << (c - 'a');
        cnt[m]++;
    }
    // Try every set of at most k letters; a string fits when its letter set is a subset.
    int best = 0;
    for (int mask = 0; mask < (1 << 10); mask++) {
        if (__builtin_popcount(mask) > k) continue;
        int total = 0;
        for (int m = 0; m < (1 << 10); m++)
            if ((m & ~mask) == 0) total += cnt[m];
        best = max(best, total);
    }
    cout << best << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        int[] cnt = new int[1 << 10];
        for (int i = 0; i < n; i++) {
            String s = next();
            int m = 0;
            for (int j = 0; j < s.length(); j++) m |= 1 << (s.charAt(j) - 'a');
            cnt[m]++;
        }
        int best = 0;
        for (int mask = 0; mask < (1 << 10); mask++) {
            if (Integer.bitCount(mask) > k) continue;
            int total = 0;
            for (int m = 0; m < (1 << 10); m++)
                if ((m & ~mask) == 0) total += cnt[m];
            best = Math.max(best, total);
        }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"math/bits"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	cnt := make([]int, 1<<10)
	for i := 0; i < n; i++ {
		m := 0
		for _, c := range token() {
			m |= 1 << (c - 'a')
		}
		cnt[m]++
	}
	best := 0
	for mask := 0; mask < 1<<10; mask++ {
		if bits.OnesCount(uint(mask)) > k {
			continue
		}
		total := 0
		for m := 0; m < 1<<10; m++ {
			if m&^mask == 0 {
				total += cnt[m]
			}
		}
		best = max(best, total)
	}
	fmt.Println(best)
}
